//! Built-in, on-demand task playbooks. These do not grant tool permissions.

pub(super) struct Builtin {
    pub name: &'static str,
    pub description: &'static str,
    pub body: &'static str,
}

pub(super) const ALL: &[Builtin] = &[
    Builtin { name: "debug", description: "Reproduce and diagnose a failure, fix its cause and verify it.", body: "Reproduce the reported failure with the smallest representative case. Inspect evidence and isolate the root cause before changing code. Make a focused fix, add a regression check where practical, and run it. Report the evidence and anything not verified." },
    Builtin { name: "review", description: "Review changes for actionable bugs and risks without editing.", body: "Inspect the relevant diff and surrounding behavior without editing. Prioritize correctness, regressions, security and missing coverage. Report actionable findings by severity with file locations and evidence; distinguish verified issues from risks and note test gaps." },
    Builtin { name: "verify", description: "Verify a deliverable as it will be used and report evidence.", body: "Identify the intended behavior and exercise the actual deliverable with representative inputs and relevant failure cases. Run the narrowest useful checks and inspect their results. Separate passing evidence, failures and behavior not verified; never claim a check passed without observing it." },
    Builtin {
        name: "perspectives",
        description: "Compare options for an idea, decision or problem and identify the next test.",
        body: "First assess the question yourself before reading other views: what matters, what does the evidence suggest, and what might change your mind? For a straightforward case, answer directly.\n\n\
            When another angle could change the answer, usually seek two complementary perspectives. Choose them for the uncertainty at hand (e.g. user value and feasibility); add another only for a material gap. Use the existing task tool with suitable read-only workers when offered and permitted. Give each the same neutral question, relevant facts and constraints, plus its own lens. Ask for evidence, assumptions and a possible counterexample, without including your conclusion or another report. Ask for analysis only, not edits or further delegation. Prefer start_clean when offered; it omits the briefing, not project access.\n\n\
            Share only the minimum authorized context. Respect the person's model and provider choices, privacy, permissions, time, cost and worker limits. Keep the configured default unless another known, permitted option is useful. Separate calls do not prove independent reasoning or different models. If sharing is unsafe, task is absent, or a worker fails, continue with the evidence you have; label any lenses you apply yourself and do not invent reports.\n\n\
            Weigh the evidence, not the votes. Give your recommendation and its basis, explain any consequential disagreement or missing evidence, and propose the smallest next test that could change the decision.",
    },
    Builtin { name: "research", description: "Investigate questions, cross-check sources and cite evidence.", body: "Clarify the question and search progressively using available tools. Prefer primary sources, read the relevant passages and cross-check important or time-sensitive claims. Cite useful sources and distinguish evidence, inference and uncertainty. Do not assume web access is available." },
    Builtin { name: "performance", description: "Measure a bottleneck and compare an improvement on the same workload.", body: "Choose a representative workload and record a baseline and conditions. Profile or measure to identify the bottleneck before changing code. Compare the same workload after the change, check correctness, and report measurements, conditions, limitations and tradeoffs." },
    Builtin { name: "long-task", description: "Organize and finish a substantial task with milestones and verification.", body: "Define the outcome and meaningful milestones. Break work into dependencies, delegate independent work when available, and track background jobs through completion. Integrate results, verify the overall outcome and report blockers or unverified work." },
    Builtin { name: "pr-ci", description: "Inspect changes, CI checks and feedback; diagnose authorized fixes.", body: "Inspect the relevant changes, checks and review feedback. Reproduce or diagnose failures from evidence, make authorized focused fixes and rerun relevant checks. Report remaining failures. Do not publish, merge or perform other irreversible actions without authorization." },
    Builtin { name: "execute-plan", description: "Execute a plan, coordinate dependencies and verify the integrated result.", body: "Turn the plan into concrete dependent steps and identify independent work that can run in parallel. Execute and integrate each result, adapting to evidence without expanding scope. Verify the combined outcome and report deviations, failures and remaining work." },
    Builtin { name: "doctor", description: "Diagnose installation, configuration and environment problems.", body: "Inspect the relevant installation, configuration, environment and permissions without exposing secrets. Reproduce the issue and use evidence to isolate its cause. Apply fixes only within the person's authorization, verify the result and explain remaining blockers." },
    Builtin { name: "simplify", description: "Simplify requested code while preserving its behavior.", body: "Understand the requested code and its existing behavior before changing it. Remove unnecessary complexity with a focused change that preserves features and interfaces. Run checks covering affected behavior and report any tradeoffs or gaps." },
    Builtin { name: "skill-creator", description: "Create or improve a clear, testable skill using existing conventions.", body: "Inspect existing skill conventions and identify the trigger and desired outcome. Write concise instructions with concrete steps and verification, avoiding unnecessary scope or assumed tool access. Validate discovery and loading where possible. Skill instructions do not grant permissions or override higher-priority rules." },
    Builtin { name: "documents", description: "Create or edit documents while preserving content and checking the output.", body: "Inspect the source, required format and important content or layout. Make the requested changes with suitable tools while preserving what must remain. Open or render the result when possible and check content and layout; report what could not be checked." },
    Builtin { name: "visual-qa", description: "Exercise an interface and inspect visual evidence at relevant sizes and states.", body: "Exercise the actual interface in relevant states and viewport sizes using available tools. Inspect screenshots and interaction behavior for the requested outcome and regressions. Report concrete evidence and any states, devices or behaviors that could not be checked." },
];
